CREATE POLICY student_term_result_update ON student_term_result FOR UPDATE TO authenticated USING (sims_private.can_student(ARRAY['RESULT.ALL.UPDATE']::text[], sims_private.nx_student_programme_enrolment_enrolment_id_student_id(sims_private.nx_student_term_registration_term_registration_id_7e00744235(student_term_result.term_registration_id)), true)) WITH CHECK (sims_private.can_student(ARRAY['RESULT.ALL.UPDATE']::text[], sims_private.nx_student_programme_enrolment_enrolment_id_student_id(sims_private.nx_student_term_registration_term_registration_id_7e00744235(student_term_result.term_registration_id)), true));
CREATE POLICY student_term_result_delete ON student_term_result FOR DELETE TO authenticated USING (sims_private.can_student(ARRAY['RESULT.ALL.DELETE']::text[], sims_private.nx_student_programme_enrolment_enrolment_id_student_id(sims_private.nx_student_term_registration_term_registration_id_7e00744235(student_term_result.term_registration_id)), true));
CREATE OR REPLACE FUNCTION sims_guard_student_term_result() RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_temp AS $$
BEGIN
    IF current_user <> 'authenticated' THEN RETURN NEW; END IF;
    IF (CASE WHEN TG_OP = 'UPDATE' THEN NEW.published_at IS DISTINCT FROM OLD.published_at ELSE NEW.published_at IS NOT NULL END) THEN
        IF NOT sims_private.can_student(ARRAY['RESULT.ALL.PUBLISH']::text[], sims_private.nx_student_programme_enrolment_enrolment_id_student_id(sims_private.nx_student_term_registration_term_registration_id_7e00744235(NEW.term_registration_id)), true) THEN
            RAISE EXCEPTION 'Not authorised to PUBLISH (student_term_result.published_at)' USING ERRCODE = '42501';
        END IF;
    END IF;
    RETURN NEW;
END $$;

